:root{
  --bg:#0d1124;
  --pink:#ff3b8d;
  --purple:#7b5cff;
  --cyan:#2ee5ff;
  --yellow:#ffd93d;
  --glass:rgba(16,20,45,0.78);
  --stroke:rgba(255,255,255,0.14);
  --text:#fff;
}
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:100%;height:100%;overflow:hidden;background:#0d1124;font-family:'Outfit',system-ui,sans-serif;color:var(--text)}
#game{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none}
#bloomCanvas{filter:blur(14px) brightness(1.2)}

/* Loader */
#loader{position:fixed;inset:0;z-index:90;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:radial-gradient(900px 600px at 50% 30%, #1c2550 0%, #0d1124 72%);transition:opacity .6s ease;text-align:center}
#loader.hide{opacity:0;pointer-events:none}
.loader-bean{font-size:64px;animation:float 1.6s ease-in-out infinite;filter:drop-shadow(0 6px 22px rgba(255,215,0,.5))}
.loader-title{font-family:'Fredoka',sans-serif;font-weight:800;font-size:34px;letter-spacing:.04em}
.loader-title span{background:linear-gradient(90deg,#ffd93d,#ff3b8d);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.loader-sub{opacity:.75;letter-spacing:.12em;font-size:11px;text-transform:uppercase}
.loader-tip{opacity:.55;font-size:11px;max-width:520px}
.bar{width:260px;height:6px;border-radius:999px;background:rgba(255,255,255,.12);overflow:hidden}
.bar span{display:block;width:40%;height:100%;border-radius:999px;background:linear-gradient(90deg,var(--pink),var(--yellow));animation:slide 1s ease-in-out infinite}

/* FG Top like screenshots */
.fg-top{position:fixed;top:0;left:0;right:0;z-index:22;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 14px;pointer-events:none}
.fg-left{display:flex;gap:12px;align-items:center;pointer-events:auto}
.rank-badge{display:flex;gap:8px;align-items:center;padding:6px 12px 6px 8px;border-radius:14px;background:linear-gradient(180deg,#ffeaa0 0%,#ffb347 100%);color:#3a2100;border:2px solid #fff;box-shadow:0 4px 14px rgba(0,0,0,.25)}
.rank-crown{font-size:22px}
.rank-info b{font-family:'Fredoka',sans-serif;font-size:16px;line-height:1}
.rank-info small{display:block;font-size:9px;opacity:.7;letter-spacing:.06em}
.name-tag{padding:8px 14px;border-radius:14px;background:linear-gradient(90deg,#26d3ff 0%,#7b5cff 100%);border:2px solid rgba(255,255,255,.9);box-shadow:0 4px 14px rgba(0,0,0,.25)}
.name-main{font-family:'Fredoka',sans-serif;font-weight:800;font-size:13px;display:flex;gap:6px;align-items:center}
.name-main small{font-size:10px;background:rgba(0,0,0,.22);padding:2px 6px;border-radius:999px}
.name-sub{font-size:10px;opacity:.85;margin-top:2px}
.fg-nav{display:flex;gap:8px;align-items:center;pointer-events:auto;background:rgba(0,0,0,.35);padding:6px 10px;border-radius:999px;backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.12)}
.nav-btn{width:38px;height:38px;border-radius:10px;border:none;background:rgba(255,255,255,.14);color:#fff;font-size:18px;cursor:pointer}
.nav-btn.active{background:#ff3b8d;color:#fff;box-shadow:0 4px 12px rgba(255,59,141,.5)}
.fg-right{display:flex;gap:8px;align-items:center;pointer-events:auto}
.curr{padding:8px 14px;border-radius:999px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(10px);font-weight:800;font-size:13px;display:flex;gap:6px;align-items:center}
.curr.crowns{color:#ffd93d}
.curr.kudos{color:#a78bff}
.icon-btn{width:38px;height:38px;border-radius:12px;border:1px solid var(--stroke);background:var(--glass);backdrop-filter:blur(12px);color:#fff;font-size:16px;cursor:pointer;display:grid;place-items:center}

/* Game HUD */
.hud{position:fixed;z-index:20;user-select:none}
.topbar{top:68px;left:14px;right:14px;display:flex;justify-content:space-between;align-items:center;gap:14px;pointer-events:none;transition:opacity .2s}
.topbar.hidden{opacity:0;pointer-events:none}
.brand{display:flex;align-items:center;gap:12px;padding:10px 16px;border-radius:18px;background:var(--glass);border:1px solid var(--stroke);backdrop-filter:blur(16px);box-shadow:0 10px 30px rgba(0,0,0,.4)}
.bean-icon{font-size:28px;filter:drop-shadow(0 2px 8px rgba(255,59,141,.6))}
.brand h1{font-family:'Fredoka',sans-serif;font-weight:800;font-size:19px;letter-spacing:.03em;line-height:1}
.brand p{font-size:9px;letter-spacing:.15em;opacity:.7;margin-top:2px}
.pill{margin-left:6px;padding:4px 10px;border-radius:999px;background:linear-gradient(90deg,var(--pink),#ff7a3d);font-size:11px;font-weight:800;letter-spacing:.06em}
.pill.fps{background:linear-gradient(90deg,#2ee5ff,#7b5cff);font-size:10px}
.stats{display:flex;gap:10px}
.stat{padding:10px 16px;border-radius:16px;background:var(--glass);border:1px solid var(--stroke);backdrop-filter:blur(16px);text-align:center;min-width:92px;pointer-events:auto}
.stat .k{display:block;font-size:10px;letter-spacing:.12em;opacity:.6}
.stat .v{font-family:'Fredoka',sans-serif;font-weight:800;font-size:20px;line-height:1;margin-top:2px}
.stat.highlight{background:linear-gradient(135deg,rgba(255,59,141,.9),rgba(123,92,255,.9));border-color:rgba(255,255,255,.2)}
.left-hud{left:14px;top:132px;display:flex;flex-direction:column;gap:12px;pointer-events:none}
.controls-card{padding:14px 16px;border-radius:16px;background:var(--glass);border:1px solid var(--stroke);backdrop-filter:blur(16px);pointer-events:auto}
.cc-title{font-size:11px;letter-spacing:.13em;opacity:.6;margin-bottom:8px;font-weight:700}
.cc-row{font-size:12px;display:flex;gap:10px;align-items:center;margin:6px 0}
.key{padding:3px 8px;border-radius:8px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.14);font-size:11px;font-weight:700;min-width:54px;text-align:center}
.minimap{width:180px;height:180px;border-radius:16px;overflow:hidden;background:var(--glass);border:1px solid var(--stroke);backdrop-filter:blur(16px);position:relative;pointer-events:auto}
#mini{width:100%;height:100%;display:block}
.mini-label{position:absolute;bottom:6px;left:50%;transform:translateX(-50%);font-size:10px;letter-spacing:.1em;opacity:.7;background:rgba(0,0,0,.45);padding:2px 8px;border-radius:999px}
.ultra-badge{padding:10px 14px;border-radius:14px;background:linear-gradient(135deg,#0f1f4a,#1c2550);border:1px solid rgba(46,229,255,.25);pointer-events:auto}
.ultra-badge span{font-size:10px;letter-spacing:.12em;color:#2ee5ff}
.ultra-badge b{display:block;font-family:'Fredoka',sans-serif;font-size:12px}
.ultra-badge small{opacity:.6;font-size:10px}
.right-hud{right:14px;top:132px;display:flex;flex-direction:column;gap:10px}
.chip{width:44px;height:44px;border-radius:14px;border:1px solid var(--stroke);background:var(--glass);backdrop-filter:blur(16px);color:#fff;font-size:18px;cursor:pointer;display:grid;place-items:center;box-shadow:0 8px 20px rgba(0,0,0,.35);transition:transform .15s}
.chip:hover{transform:translateY(-2px) scale(1.04)}
.bottom{left:50%;bottom:14px;transform:translateX(-50%);width:min(760px,calc(100vw - 28px));display:flex;flex-direction:column;gap:10px;align-items:center;transition:opacity .2s}
.bottom.hidden{opacity:0;pointer-events:none}
.progress-wrap{width:100%;padding:12px 16px 14px;border-radius:18px;background:var(--glass);border:1px solid var(--stroke);backdrop-filter:blur(16px);box-shadow:0 10px 30px rgba(0,0,0,.4)}
.progress-labels{display:flex;justify-content:space-between;font-size:10px;letter-spacing:.11em;opacity:.7;margin-bottom:8px}
.progress-track{position:relative;height:18px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);overflow:hidden}
.progress-fill{position:absolute;inset:2px auto 2px 2px;width:0%;border-radius:999px;background:linear-gradient(90deg,var(--pink) 0%, var(--purple) 55%, var(--cyan) 100%);transition:width .15s}
.progress-bean{position:absolute;top:50%;transform:translate(-50%,-50%);left:0%;font-size:18px;filter:drop-shadow(0 2px 6px rgba(0,0,0,.5));transition:left .15s;pointer-events:none}
.progress-bots{position:absolute;inset:0}
.bot-dot{position:absolute;top:50%;width:8px;height:8px;border-radius:50%;transform:translate(-50%,-50%);border:2px solid rgba(255,255,255,.9);box-shadow:0 2px 6px rgba(0,0,0,.4)}
.players-dots{display:flex;gap:4px;margin-top:8px;flex-wrap:wrap;justify-content:center}
.pdot{width:8px;height:8px;border-radius:50%;border:1px solid rgba(255,255,255,.5)}
.hint{padding:8px 14px;border-radius:999px;background:var(--glass);border:1px solid var(--stroke);backdrop-filter:blur(16px);font-size:12px;opacity:.9;white-space:nowrap}
.hint .kbd{padding:2px 6px;border-radius:6px;background:rgba(255,255,255,.14);font-weight:700;font-size:11px}

/* FG MENU — exact Fall Guys replicate (teal / green / concentric) */
.fg-menu{padding:0;background:none;backdrop-filter:none;align-items:stretch;justify-content:stretch;display:flex;overflow:hidden}
.fg-menu.hidden{display:none}
.menu-bg{position:absolute;inset:0;background:
  repeating-radial-gradient(circle at 50% 42%, rgba(255,255,255,0.10) 0 2px, transparent 2px 26px),
  radial-gradient(900px 700px at 50% 45%, rgba(255,255,255,0.22) 0%, transparent 62%),
  linear-gradient(180deg, #3cc7d0 0%, #2ebfae 28%, #7fd6a8 62%, #c8f0a8 100%);
  opacity:1}
.menu-right{position:absolute;right:14px;top:74px;bottom:14px;width:min(360px, calc(100vw - 28px));display:flex;flex-direction:column;gap:12px;z-index:2}
.prime-card{position:relative;padding:14px 16px;border-radius:16px;background:linear-gradient(90deg,#00d084 0%,#00b56a 100%);border:2px solid #fff;color:#fff;box-shadow:0 8px 22px rgba(0,0,0,.25);overflow:hidden}
.prime-head{font-size:10px;letter-spacing:.12em;opacity:.85;text-transform:uppercase}
.prime-body b{display:block;font-family:'Fredoka',sans-serif;font-size:14px}
.prime-body small{opacity:.8;font-size:11px}
.prime-char{position:absolute;right:8px;top:50%;transform:translateY(-50%);font-size:44px}
.challenges{padding:14px;border-radius:16px;background:rgba(0,0,0,.72);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(12px)}
.ch-head{text-align:center;font-family:'Fredoka',sans-serif;font-weight:800;letter-spacing:.06em;background:#2ec5ff;color:#0a1030;padding:8px;border-radius:10px;margin:-6px -6px 12px}
.ch-item{display:flex;gap:10px;align-items:center;padding:10px;border-radius:12px;background:rgba(255,255,255,.06);margin-bottom:8px;border:1px solid rgba(255,255,255,.06)}
.ch-item .hex{width:16px;height:16px;border-radius:4px;border:2px solid rgba(255,255,255,.4);transform:rotate(45deg);flex-shrink:0}
.ch-item b{font-size:12px}
.ch-bar{height:6px;border-radius:999px;background:rgba(255,255,255,.15);margin-top:6px;overflow:hidden}
.ch-bar span{display:block;height:100%;background:linear-gradient(90deg,#ffd93d,#ff3b8d);width:0}
.ch-item small{margin-left:auto;font-size:11px;opacity:.8;display:flex;gap:6px}
.ch-item small i{padding:2px 6px;border-radius:999px;background:rgba(255,217,61,.2);font-style:normal}
.ch-time{text-align:center;font-size:11px;opacity:.7}
.btn-selector{padding:14px;border-radius:14px;border:2px solid #fff;background:#2ec5ff;color:#0a1030;font-family:'Fredoka',sans-serif;font-weight:800;letter-spacing:.05em;cursor:pointer;box-shadow:0 6px 16px rgba(0,0,0,.25)}
.btn-selector small{margin-left:8px;padding:2px 6px;border-radius:6px;background:rgba(0,0,0,.15);font-size:10px}
.btn-ready{padding:18px;border-radius:16px;border:none;background:linear-gradient(90deg,#ff3b8d,#ff6b9d);color:#fff;font-family:'Fredoka',sans-serif;font-weight:800;font-size:22px;cursor:pointer;box-shadow:0 10px 24px rgba(255,59,141,.45)}
.btn-ready small{display:block;font-size:11px;opacity:.9;letter-spacing:.08em}
.btn-row{display:flex;gap:8px}
.btn-mini{flex:1;padding:12px;border-radius:12px;border:2px solid #fff;background:#7b5cff;color:#fff;font-weight:800;cursor:pointer}
.btn-mini.alt{background:linear-gradient(90deg,#ffd93d,#ff9f1c);color:#2a1400}
.lan-badge{padding:10px 14px;border-radius:12px;background:rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.12);font-size:11px;text-align:center}
.menu-center{position:absolute;left:50%;top:52%;transform:translate(-50%,-50%);width:min(760px, 90vw);height:52vh;display:flex;align-items:end;justify-content:center;gap:22px;z-index:1;pointer-events:none}
.not-ready{position:absolute;top:-22px;display:flex;flex-direction:column;align-items:center;gap:4px;padding:8px 14px;border-radius:999px;background:rgba(0,0,0,.58);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(8px);font-size:11px;box-shadow:0 6px 16px rgba(0,0,0,.25)}
.not-ready span{font-weight:800;letter-spacing:.06em;color:#2ec5ff}
.not-ready small{background:#2ec5ff;color:#001030;padding:3px 10px;border-radius:999px;font-weight:800;font-size:11px}
.not-ready-left{left:22%} .not-ready-right{right:26%}
.season-progress{position:fixed;left:14px;bottom:14px;width:360px;padding:12px 14px;border-radius:16px;background:rgba(0,0,0,.78);border:1px solid rgba(255,255,255,.16);pointer-events:auto;z-index:3;box-shadow:0 8px 22px rgba(0,0,0,.35)}
.sp-head{font-size:11px;font-weight:800;letter-spacing:.06em;display:flex;justify-content:space-between}
.sp-head span{padding:2px 8px;border-radius:999px;background:#ff3b8d;color:#fff}
.sp-bar{margin-top:8px;height:14px;border-radius:999px;background:rgba(255,255,255,.15);overflow:hidden;position:relative}
.sp-bar span{position:absolute;inset:0;display:grid;place-items:center;font-size:10px;font-weight:800;background:linear-gradient(90deg,#ff3b8d,#ff7ab6);width:100%}

/* Modals */
.overlay{position:fixed;inset:0;z-index:40;display:grid;place-items:center;padding:18px;background:radial-gradient(900px 700px at 50% 20%, rgba(123,92,255,.28) 0%, rgba(13,17,36,.94) 65%);backdrop-filter:blur(8px)}
.overlay.hidden{display:none}
.modal{width:min(780px,100%);max-height:92vh;overflow:auto;border-radius:26px;background:linear-gradient(180deg, rgba(26,31,70,.96) 0%, rgba(16,20,45,.98) 100%);border:1px solid rgba(255,255,255,.14);box-shadow:0 24px 80px rgba(0,0,0,.6);padding:24px;text-align:center}
.modal-badge{display:inline-block;padding:6px 14px;border-radius:999px;background:linear-gradient(90deg,var(--pink),var(--yellow));color:#1a1030;font-weight:800;letter-spacing:.08em;font-size:11px;margin-bottom:12px}
.modal h2{font-family:'Fredoka',sans-serif;font-weight:800;font-size:clamp(26px,5vw,38px);line-height:.95}
.modal h2 .accent{background:linear-gradient(90deg,var(--cyan),var(--yellow));-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.lead{margin:10px auto 16px;max-width:640px;opacity:.82;line-height:1.5;font-size:13px}
.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:left;margin:16px 0}
.sg{padding:12px;border-radius:14px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08)}
.sg label{font-size:11px;letter-spacing:.08em;opacity:.7;display:block;margin-bottom:6px}
.sg select,.sg input[type="range"],.sg input[type="text"]{width:100%;padding:8px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(0,0,0,.35);color:#fff}
.sg.tog{grid-column:span 1}
.perf{display:flex;justify-content:center;gap:14px;margin:14px 0}
.perf div{padding:10px 14px;border-radius:14px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);min-width:86px}
.perf span{font-family:'Fredoka',sans-serif;font-weight:800;font-size:20px;display:block}
.perf label{font-size:10px;letter-spacing:.1em;opacity:.6}
.settings-actions{display:flex;gap:10px;margin-top:10px}
.cta{flex:1;padding:16px 20px;border-radius:16px;border:none;background:linear-gradient(90deg,var(--pink),var(--purple));color:#fff;font-family:'Fredoka',sans-serif;font-weight:800;font-size:16px;cursor:pointer;box-shadow:0 12px 30px rgba(255,59,141,.35)}
.ghost{flex:1;padding:16px;border-radius:16px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.06);color:#fff;font-weight:800;cursor:pointer}
.muted{opacity:.5;font-size:10px;display:block;margin-top:8px}

/* MP */
.mp-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:left;margin:16px 0}
.mp-card{padding:16px;border-radius:16px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08)}
.mp-card h3{font-family:'Fredoka',sans-serif;font-size:14px;letter-spacing:.06em}
.mp-card p{opacity:.7;font-size:12px;margin:6px 0 10px}
.code{margin-top:10px;padding:10px;border-radius:12px;background:rgba(0,0,0,.35);border:1px dashed rgba(255,255,255,.2);font-weight:800;letter-spacing:.12em;display:flex;justify-content:space-between;align-items:center}
.code.hidden{display:none}
.copy{padding:6px 10px;border-radius:8px;border:none;background:#2ee5ff;color:#001030;font-weight:800;cursor:pointer}
#mp-join-code{margin-bottom:8px}
.status{margin-top:8px;padding:8px;border-radius:10px;background:rgba(0,0,0,.35);font-size:11px}
.mp-signal{margin:12px 0;text-align:left}
.mp-signal details{padding:12px;border-radius:14px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08)}
.sig-row{display:flex;gap:8px;margin:8px 0}
.sig-row textarea{flex:1;height:66px;padding:8px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(0,0,0,.35);color:#fff;font-size:10px}
.mp-bots{padding:12px;border-radius:14px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08)}
.mp-avatars{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-top:8px}
.mp-avatars span{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:14px;border:2px solid rgba(255,255,255,.8)}

/* Finish */
.finish-modal .big-icon{font-size:64px;margin-bottom:10px;filter:drop-shadow(0 6px 20px rgba(255,215,0,.4))}
.finish-modal h2{font-family:'Fredoka',sans-serif;font-size:34px;font-weight:800}
.finish-stats{display:flex;justify-content:center;gap:14px;margin:16px 0}
.finish-stats div{padding:12px 16px;border-radius:16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.08);min-width:86px}
.finish-stats span{font-family:'Fredoka',sans-serif;font-weight:800;font-size:22px;display:block}
.finish-stats label{font-size:10px;letter-spacing:.1em;opacity:.6}
.finish-actions{display:flex;gap:10px}

/* Touch */
.touch{position:fixed;inset:auto 0 0 0;z-index:25;display:none;justify-content:space-between;align-items:end;padding:14px 18px 18px;pointer-events:none}
.stick{width:124px;height:124px;border-radius:50%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);backdrop-filter:blur(12px);position:relative;pointer-events:auto;touch-action:none}
.stick-inner{position:absolute;left:50%;top:50%;width:56px;height:56px;border-radius:50%;background:linear-gradient(135deg,var(--pink),var(--purple));transform:translate(-50%,-50%);box-shadow:0 6px 20px rgba(0,0,0,.4)}
.touch-right{display:flex;gap:12px;pointer-events:auto}
.tbtn{width:84px;height:84px;border-radius:22px;border:1px solid rgba(255,255,255,.14);background:rgba(16,20,45,.7);backdrop-filter:blur(12px);color:#fff;font-weight:800;font-size:20px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;box-shadow:0 8px 24px rgba(0,0,0,.4)}
.tbtn small{font-size:10px;letter-spacing:.1em;opacity:.7}
.toast{position:fixed;left:50%;top:88px;transform:translateX(-50%);z-index:50;padding:12px 18px;border-radius:999px;background:linear-gradient(90deg,var(--pink),var(--purple));color:#fff;font-weight:800;letter-spacing:.03em;box-shadow:0 10px 30px rgba(0,0,0,.4);transition:opacity .3s, transform .3s}
.toast.hidden{opacity:0;transform:translateX(-50%) translateY(-10px);pointer-events:none}

@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes slide{0%{transform:translateX(-120%)}100%{transform:translateX(320%)}}

@media (max-width:640px){
  .fg-top{flex-wrap:wrap;justify-content:center;padding:6px}
  .fg-left .name-tag{display:none}
  .menu-right{width:calc(100vw - 20px);right:10px;left:10px;top:auto;bottom:10px;max-height:46vh;overflow:auto}
  .menu-center{top:36%;height:44vh}
  .season-progress{width:calc(100vw - 20px);left:10px;right:10px;bottom:44vh}
  .topbar{flex-direction:column;align-items:stretch;top:62px}
  .brand{justify-content:center}
  .left-hud{display:none}
  .touch{display:flex}
  .bottom{width:calc(100vw - 16px);bottom:110px}
  .settings-grid,.mp-grid{grid-template-columns:1fr}
  .right-hud{top:auto;bottom:200px}
}

